-- mr_berk GENTAHAX MCP Template: Discord Webhook
-- Risk: DUSUK (oyun acisindan) — sadece kendi verinizi gonderin
local WEBHOOK_URL = 'BURAYA_WEBHOOK_URL'

local function bildir(baslik, mesaj)
    sendWebhook(WEBHOOK_URL, {
        username = 'GENTAHAX Bot',
        content = '',
        useEmbeds = true,
        embeds = {
            {
                title = baslik,
                description = mesaj,
                color = 3447003,
                footer = { text = 'mr_berk GENTAHAX MCP' }
            }
        }
    })
end

-- Ornek: oyuna girince bildir
AddHook('OnTextPacket', 'giris', function(flag, pkt)
    if pkt:find('action%|log') then
        bildir('Oyun Bildirimi', 'Baglanti kuruldu: ' .. tostring(getWorld() and getWorld().name or '?'))
    end
end)
